'use strict';
function qrexEffectiveSectionResult(i,section,result){return i.data.section_flags?.[section]==='pass'?'pass':result;}

function recordMetricTable(i,m){
    if(i.data.section_flags?.[m.section]!=='pass')return metricTable(i,m,true);
    const values=i.data.measurements?.[m.key]||[],limit=i.spec?.limits?.[m.key]||{};
    const rows=Array.from({length:m.samples},(_,n)=>`<tr data-reading-row="${esc(m.key)}-${n}"><td class="numeric">${String(n+1).padStart(2,'0')}</td><td>${esc(values[n]??'Not recorded')}</td><td class="sample-status">${status('pass')}</td><td class="reason">Section PASS override<br>Recorded assessment: ${esc(reasonText(values[n],limit,readingResult(values[n],limit)))}</td></tr>`).join('');
    const spec=limit.na?esc(rangeText(limit,m.unit)):`<div><small>Minimum${m.unit?' ('+esc(m.unit)+')':''}</small><span class="spec-number">${limit.min??'N/A'}</span></div>${limit.nominal!=null?`<div><small>Nominal</small><span class="spec-number">${limit.nominal}</span></div>`:''}<div><small>Maximum${m.unit?' ('+esc(m.unit)+')':''}</small><span class="spec-number">${limit.max??'No upper limit'}</span></div>`;
    const reason=i.data.fields[m.key+'_defect'];
    return `<div class="measure-header"><div><h2>${esc(m.label)}</h2><p>${m.samples} ${m.samples===1?'reading':'sample readings'}${m.unit?' &middot; '+esc(m.unit):''}</p></div><div id="metric-result-${esc(m.key)}">${status('pass')}</div></div><div class="spec-strip">${spec}<span class="spec-source">${esc(i.spec?.reference||'')}<br>${esc(i.glove_type)} &middot; ${esc(sizeLabel(i))}</span></div><table class="reading-table" aria-label="${esc(m.label)} samples"><thead><tr><th>Sample</th><th>Reading${m.unit?' ('+esc(m.unit)+')':''}</th><th>Result</th><th>Assessment</th></tr></thead><tbody>${rows}</tbody></table><div id="reading-stats-${esc(m.key)}" class="reading-stats">${readingStats(values)}</div>${reason?`<p class="muted record-note">Recorded failure reason: ${esc(reason)}</p>`:''}`;
}
async function record(q,ticket){const i=await api('inspection',null,{id:q.get('id')});if(ticket!==S.routeTicket)return;S.record=i;const e=i.evaluation;const supervisor=['admin','supervisor'].includes(S.user.role);const definitions=S.meta.products[i.product];$('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">Inspection record · QI-${String(i.id).padStart(5,'0')}</p><h1>SO ${esc(i.so_number)} / ${esc(i.unit_label)}</h1><p>${productLabel(i.product)} · ${esc(i.glove_type)} · Size ${esc(sizeLabel(i))} · ${dateText(i.updated_at)}</p></div><div class="actions">${status(i.state)}${i.editable?`<a class="btn primary" href="#inspection?id=${i.id}">${icon('edit')} Continue draft</a>`:''}${supervisor&&i.state==='submitted'?button('Verify inspection','verify','user-check','primary'):''}${supervisor&&i.state!=='draft'?button('Reopen for editing','reopen','edit'):''}${button('Print','print','printer')}</div></div><div class="record-summary"><section class="form-surface"><div class="form-section-head"><h2>Inspection result</h2>${status(i.result)}</div><div class="form-content"><div class="review-summary"><div><h2>${e.passed} passed <span class="muted" style="font-size:15px;font-weight:400"> / ${e.failed} failed checks</span></h2><p>${e.missing.length?e.missing.length+' incomplete entries':'All required inspection entries recorded'}</p></div></div><dl class="key-values">${Object.entries({'Sales order':i.so_number,'Product':i.glove_type,'Size':sizeLabel(i),'Unit':i.unit_label,'Customer':i.common.customer,'Factory':i.common.factory,'Item number':i.common.item_no,'Lot number':i.common.lot_no,'Country':i.common.country,'Brand':i.common.brand,'Colour':i.common.colour,'Product type':i.common.product_type,'Created by':i.inspector_name,'Inspector ID':i.data.fields.inspector_id,'Specification':i.spec?.reference||'Not available','Specification revision':i.spec?.revision||'Not available'}).map(([k,v])=>`<div><dt>${esc(k)}</dt><dd>${esc(v||'Not recorded')}</dd></div>`).join('')}</dl>${supervisor&&i.state==='draft'?button('Assign approved specification','apply-spec','ruler-measure','small'):''}</div></section><section><div class="section-head"><h2>Attention & verification</h2></div><div class="surface"><div class="form-content">${e.issues.length?e.issues.map(issue=>recordIssueLink(i,issue)).join(''):`<div class="info-band">${icon('circle-check')}<span>No failed checks recorded.</span></div>`}<div class="divider"></div><h3>Verification history</h3>${i.verifications.length?i.verifications.map(v=>`<div class="record-section"><div class="section-head"><strong>${esc(v.reviewer)}</strong>${status(v.decision)}</div><p class="muted" style="font-size:12px;line-height:1.6">${esc(v.notes)}</p><small class="muted">${dateText(v.created_at)} · Inspection version ${v.inspection_version}</small></div>`).join(''):'<p class="muted" style="font-size:12px;margin-top:12px">This inspection has not been verified.</p>'}</div></div></section></div><section class="form-surface"><div class="form-section-head"><h2>Inspection details</h2><span class="muted" style="font-size:12px">Record version ${i.version}</span></div><div class="form-content"><details class="record-section"><summary>Unit information ${status(e.sections.information)}</summary><dl class="key-values">${Object.entries(i.data.fields).filter(([k])=>!['remarks','defect_remarks'].includes(k)).map(([k,v])=>`<div><dt>${esc(k.replaceAll('_',' '))}</dt><dd>${esc(v||'Not recorded')}</dd></div>`).join('')}</dl></details><details class="record-section" id="record-defects"><summary>Visual inspection ${status(e.sections.defects)}</summary><table><thead><tr><th>Category</th><th>Defect</th><th>Quantity</th></tr></thead><tbody>${i.data.defects.map(d=>`<tr><td>${esc(d.category)}</td><td>${esc(d.name)}</td><td>${d.quantity}</td></tr>`).join('')||'<tr><td colspan="3">No defects recorded.</td></tr>'}</tbody></table><p class="muted" style="margin-top:12px">${esc(i.data.fields.defect_remarks)}</p></details><details class="record-section" id="record-tests"><summary>Performance tests ${status(e.sections.tests)}</summary>${definitions.tests.map(test=>`<div class="review-row" id="record-${test.key}"><span>${test.label}</span><span>${(i.data.tests[test.key]||[]).map(status).join(' ')}</span></div>`).join('')}${definitions.metrics.filter(m=>m.section==='tests').map(m=>`<div id="record-${m.key}">${recordMetricTable(i,m)}</div>`).join('')}</details><details class="record-section" id="record-measurements"><summary>Measurements ${status(e.sections.measurements)}</summary>${definitions.metrics.filter(m=>m.section==='measurements').map(m=>`<details class="record-section" id="record-${m.key}"><summary>${m.label} ${status(e.checks[m.key].result)}</summary>${recordMetricTable(i,m)}</details>`).join('')}</details><details class="record-section"><summary>Inspection remarks ${icon('message')}</summary><p>${esc(i.data.fields.remarks||'No remarks recorded.')}</p></details><details class="record-section" id="audit-details"><summary>Audit trail ${icon('history')}</summary><div id="audit-body" class="muted">Open to load record history.</div></details></div></section>`;$('#audit-details').ontoggle=async event=>{if(!event.target.open||event.target.dataset.loaded)return;try{const a=await api('audit',null,{id:i.id});$('#audit-body').innerHTML=`<div class="timeline">${a.rows.map(r=>`<div class="timeline-item"><strong>${esc(r.action.replaceAll('_',' '))}</strong><p>${esc(r.actor||'System')} · ${esc(r.created_at)}${r.details.notes?'<br>'+esc(r.details.notes):''}</p><details><summary style="font-size:11px;color:var(--muted);cursor:pointer;margin-top:6px">Change details</summary><pre class="data-change">${esc(JSON.stringify(r.details,null,2))}</pre></details></div>`).join('')}</div>`;event.target.dataset.loaded='1';}catch(err){$('#audit-body').textContent=err.message;}};}
function recordIssueLink(i,issue){if(i.editable)return `<a class="issue-link failure" href="#inspection?id=${i.id}&section=${esc(issue.section)}&metric=${esc(issue.key)}">${icon('alert-circle')}<span>${esc(issue.message)}</span></a>`;return `<button class="issue-link failure" data-action="record-issue" data-section="${esc(issue.section)}" data-key="${esc(issue.key)}">${icon('alert-circle')}<span>${esc(issue.message)}</span></button>`;}
async function verifyDialog(){const i=S.record;const f=modal('Verify inspection',`<div class="notice neutral">${icon('user-check')}<div>QI-${String(i.id).padStart(5,'0')} · ${esc(i.unit_label)}<br>Calculated result: ${labels[i.result]}</div></div><div class="field-grid two">${select('decision','Decision',[{value:'released',label:'Release (complete PASS only)'},{value:'held',label:'Hold for further review'},{value:'rejected',label:'Reject'}],i.result==='pass'?'released':i.result==='fail'?'rejected':'held','required')}<label class="field span-all"><span>Verification notes *</span><textarea name="notes" minlength="5" required placeholder="Record your decision and supporting observations"></textarea></label></div>`,`<button type="button" class="btn" data-action="close-dialog">Cancel</button><button type="submit" class="btn primary">${icon('user-check')} Confirm verification</button>`);f.onsubmit=async ev=>{ev.preventDefault();const b=$('button[type=submit]',f),label=b.innerHTML;b.disabled=true;b.classList.add('is-busy');b.innerHTML=icon('loader-2')+' Verifying';try{await api('verify',{id:i.id,version:i.version,...formValues(f)});closeModal();toast('Verification recorded.');await route();}catch(e){modalError(e);b.disabled=false;b.classList.remove('is-busy');b.innerHTML=label;}};}
function reopenDialog(){const i=S.record;const f=modal('Reopen inspection',`<p>The existing readings, defects, unit identity and verification history will be retained. A new submission and verification will be needed.</p><label class="field"><span>Reason for reopening *</span><textarea name="notes" required minlength="5"></textarea></label>`,`<button type="button" class="btn" data-action="close-dialog">Cancel</button><button type="submit" class="btn primary">Reopen for editing</button>`);f.onsubmit=async e=>{e.preventDefault();const b=$('button[type=submit]',f),label=b.innerHTML;b.disabled=true;b.classList.add('is-busy');b.innerHTML=icon('loader-2')+' Reopening';try{await api('reopen',{id:i.id,version:i.version,...formValues(f)});closeModal();location.hash='inspection?id='+i.id;}catch(err){modalError(err);b.disabled=false;b.classList.remove('is-busy');b.innerHTML=label;}};}
async function rejections(q,ticket){const d=await api('rejections',null,Object.fromEntries(q));if(ticket!==S.routeTicket)return;$('#main').innerHTML=`<div class="page-heading"><div><h1>Rejection follow-up</h1><p>Investigate failures, record containment, and track actions to closure.</p></div></div><div class="filters"><select id="rejection-status" aria-label="Investigation status">${options(['open','investigating','contained','closed'].map(v=>({value:v,label:labels[v]})),q.get('status'),'All investigations')}</select><span class="muted" style="font-size:12px">${d.rows.length} investigations</span></div><div class="surface">${d.rows.length?`<div class="table-wrap"><table><thead><tr><th>Order / unit</th><th>Product</th><th>Result</th><th>Follow-up</th><th>Owner</th><th>Last action</th><th></th></tr></thead><tbody>${d.rows.map(r=>`<tr><td><a class="row-link" href="#record?id=${r.inspection_id}">SO ${esc(r.so_number)}</a><small>${esc(r.unit_label)} · QI-${String(r.inspection_id).padStart(5,'0')}</small></td><td>${esc(r.glove_type)}<small>${productLabel(r.product)} · ${esc(sizeLabel(r))}</small></td><td>${status(r.result)}</td><td>${status(r.status)}</td><td>${esc(r.owner||'Unassigned')}</td><td>${dateText(r.updated_at)}<small>${esc(r.notes.slice(0,65))}</small></td><td>${['admin','supervisor'].includes(S.user.role)?button('Update','investigation','edit','small',`data-id="${r.inspection_id}"`):''}</td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('shield-check')}<h3>No investigations in this queue</h3><p>Submitted inspections with failed checks appear here for follow-up.</p></div>`}</div>`;S.rejections=d.rows;$('#rejection-status').onchange=e=>location.hash='rejections?status='+e.target.value;}
function investigationDialog(id){const r=S.rejections.find(r=>Number(r.inspection_id)===Number(id));const f=modal('Update investigation',`<p>SO ${esc(r.so_number)} · ${esc(r.unit_label)}</p><div class="field-grid two">${select('status','Follow-up status',['open','investigating','contained','closed'].map(v=>({value:v,label:labels[v]})),r.status,'required')}<label class="field span-all"><span>Investigation / containment notes *</span><textarea name="notes" required minlength="5">${esc(r.notes)}</textarea></label></div><p style="margin-top:15px">This records follow-up action. It does not change the inspection result or verification decision.</p>`,`<button class="btn" type="button" data-action="close-dialog">Cancel</button><button class="btn primary" type="submit">Save follow-up</button>`);f.onsubmit=async e=>{e.preventDefault();try{await api('rejection',{id:r.inspection_id,...formValues(f)});closeModal();toast('Investigation updated.');await route();}catch(err){modalError(err);}};}
async function reports(q,ticket){const d=await api('reports',null,Object.fromEntries(q));if(ticket!==S.routeTicket)return;const totals=d.products.reduce((a,p)=>({total:a.total+Number(p.total),passed:a.passed+Number(p.passed),failed:a.failed+Number(p.failed),held:a.held+Number(p.held)}),{total:0,passed:0,failed:0,held:0});const max=Math.max(1,...d.trend.map(x=>Number(x.total)));const top=Math.max(1,...d.defects.map(x=>Number(x.quantity)));$('#main').innerHTML=`<div class="page-heading"><div><h1>Quality reports</h1><p>Submitted inspection outcomes and observed defect quantities.</p></div></div><form id="report-filter" class="filters">${input('from','Submission date from',d.period.from,'date','required')}${input('to','Submission date to',d.period.to,'date','required')}<button type="submit" class="btn">${icon('filter')} Apply period</button></form><div class="metrics">${[['Submitted inspections',totals.total],['Pass rate',totals.total?(totals.passed/totals.total*100).toFixed(1)+'%':'N/A'],['Failed inspections',totals.failed],['Requires review',totals.held]].map(([label,value])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">Selected submission period</div></div>`).join('')}</div><div class="report-grid"><section class="report-panel"><div class="section-head"><h2>Inspection trend</h2><div class="legend"><span><i></i>PASS</span><span><i class="red"></i>FAIL</span></div></div>${d.trend.length?`<div class="chart" role="img" aria-label="Daily submitted inspection pass and fail counts">${d.trend.map(t=>`<div class="bar-column" title="${t.day}: ${t.passed} pass, ${t.failed} fail"><div class="bar-pair"><div class="bar" style="height:${Number(t.passed)/max*100}%"></div><div class="bar fail" style="height:${Number(t.failed)/max*100}%"></div></div><small>${t.day.slice(5)}</small></div>`).join('')}</div><details style="margin-top:15px"><summary class="muted" style="font-size:12px;cursor:pointer">View daily values</summary><table><thead><tr><th>Date</th><th>Total</th><th>PASS</th><th>FAIL</th></tr></thead><tbody>${d.trend.map(t=>`<tr><td>${t.day}</td><td>${t.total}</td><td>${t.passed}</td><td>${t.failed}</td></tr>`).join('')}</tbody></table></details>`:'<div class="empty"><p>No submissions in this period.</p></div>'}</section><section class="report-panel"><h2>Most frequent defects</h2><p class="muted" style="font-size:12px;margin-top:6px">Quantities recorded on submitted inspection units.</p>${d.defects.map(x=>`<div class="horizontal-bar"><span>${esc(x.name)}</span><div><i style="width:${Number(x.quantity)/top*100}%"></i></div><strong>${x.quantity}</strong></div>`).join('')||'<div class="empty"><p>No defects recorded in this period.</p></div>'}</section><section class="report-panel span-all"><h2>Product results</h2><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Product</th><th>Submitted</th><th>PASS</th><th>FAIL</th><th>Requires review</th><th>Pass rate</th></tr></thead><tbody>${d.products.map(p=>`<tr><td>${productLabel(p.product)}</td><td>${p.total}</td><td>${p.passed}</td><td>${p.failed}</td><td>${p.held}</td><td>${(Number(p.passed)/Number(p.total)*100).toFixed(1)}%</td></tr>`).join('')||'<tr><td colspan="6">No data in this period.</td></tr>'}</tbody></table></div></section></div>`;$('#report-filter').onsubmit=e=>{e.preventDefault();const p=formValues(e.target);if(p.from>p.to){toast('Start date must be before the end date.',true);return;}location.hash='reports?'+new URLSearchParams(p);};}
const reportCachePrefix='qrex-daily-report-v2';
function reportToday(){const d=new Date(),pad=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`;}
function reportCacheKey(date){return `${reportCachePrefix}:${S.user?.id||0}:${date}`;}
function reportCacheRead(date){try{return JSON.parse(localStorage.getItem(reportCacheKey(date))||'null');}catch{return null;}}
function reportCacheWrite(date,data){const entry={date,user_id:S.user?.id||0,executed_at:new Date().toISOString(),data};try{localStorage.setItem(reportCacheKey(date),JSON.stringify(entry));}catch(e){toast('Report loaded, but browser cache is full or disabled.',true);}return entry;}
function reportCacheDelete(date){try{localStorage.removeItem(reportCacheKey(date));}catch{}}
function reportCacheList(){const rows=[];try{for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key||!key.startsWith(`${reportCachePrefix}:${S.user?.id||0}:`))continue;const row=JSON.parse(localStorage.getItem(key)||'null');if(row?.date&&row?.data)rows.push(row);}}catch{}return rows.sort((a,b)=>String(b.date).localeCompare(String(a.date))||String(b.executed_at).localeCompare(String(a.executed_at)));}
function reportExecutedText(value){return value?new Date(value).toLocaleString('en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'Not cached';}
function reportNormalize(data,date){return {...data,period:{...(data.period||{}),date:date||data.period?.date||data.period?.from||reportToday()}};}
function savedReportsDialog(){const rows=reportCacheList();modal('Saved daily reports',rows.length?`<div class="table-wrap"><table><thead><tr><th>Report date</th><th>Executed</th><th>Submitted</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.date)}</strong></td><td>${esc(reportExecutedText(r.executed_at))}</td><td>${Number(r.data?.products?.reduce((a,p)=>a+Number(p.total||0),0)||0).toLocaleString()}</td><td><div class="record-actions">${button('Open','report-cache-open','folder-open','small',`data-date="${esc(r.date)}"`)}${button('Delete','report-cache-delete','trash','small danger',`data-date="${esc(r.date)}"`)} </div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${icon('database')}<h3>No saved daily report</h3><p>Execute a report for a day first. The report will be kept here for quick viewing.</p></div>`,button('Close','close-dialog',null),true);}
function renderDailyReport(d,cacheEntry=null,fromCache=false){const date=d.period?.date||d.period?.from||reportToday();const totals=d.products.reduce((a,p)=>({total:a.total+Number(p.total),passed:a.passed+Number(p.passed),failed:a.failed+Number(p.failed),held:a.held+Number(p.held)}),{total:0,passed:0,failed:0,held:0});const max=Math.max(1,...d.trend.map(x=>Number(x.total)));const top=Math.max(1,...d.defects.map(x=>Number(x.quantity)));const cacheNote=cacheEntry?`${fromCache?'Loaded from cache':'Cached'} · Executed ${reportExecutedText(cacheEntry.executed_at)}`:'Not cached yet';$('#main').innerHTML=`<div class="page-heading"><div><h1>Quality reports</h1><p>Daily submitted inspection outcomes and observed defect quantities.</p></div><div class="actions">${button('Saved reports','report-cache-list','database')}</div></div><form id="report-filter" class="filters">${input('date','Submission date',date,'date','required')}<button type="submit" class="btn primary">${icon('player-play')} Execute report</button>${reportCacheRead(date)?button('View cached','report-cache-open','folder-open','',`data-date="${esc(date)}"`):''}<span class="tag">${esc(cacheNote)}</span></form><div class="metrics">${[['Submitted inspections',totals.total],['Pass rate',totals.total?(totals.passed/totals.total*100).toFixed(1)+'%':'N/A'],['Failed inspections',totals.failed],['Requires review',totals.held]].map(([label,value])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">Selected submission day</div></div>`).join('')}</div><div class="report-grid"><section class="report-panel"><div class="section-head"><h2>Inspection trend</h2><div class="legend"><span><i></i>PASS</span><span><i class="red"></i>FAIL</span></div></div>${d.trend.length?`<div class="chart" role="img" aria-label="Submitted inspection pass and fail counts for ${esc(date)}">${d.trend.map(t=>`<div class="bar-column" title="${t.day}: ${t.passed} pass, ${t.failed} fail"><div class="bar-pair"><div class="bar" style="height:${Number(t.passed)/max*100}%"></div><div class="bar fail" style="height:${Number(t.failed)/max*100}%"></div></div><small>${t.day.slice(5)}</small></div>`).join('')}</div><table><thead><tr><th>Date</th><th>Total</th><th>PASS</th><th>FAIL</th></tr></thead><tbody>${d.trend.map(t=>`<tr><td>${t.day}</td><td>${t.total}</td><td>${t.passed}</td><td>${t.failed}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><p>No submissions on this day.</p></div>'}</section><section class="report-panel"><h2>Most frequent defects</h2><p class="muted" style="font-size:12px;margin-top:6px">Quantities recorded on submitted inspection units for this day.</p>${d.defects.map(x=>`<div class="horizontal-bar"><span>${esc(x.name)}</span><div><i style="width:${Number(x.quantity)/top*100}%"></i></div><strong>${x.quantity}</strong></div>`).join('')||'<div class="empty"><p>No defects recorded on this day.</p></div>'}</section><section class="report-panel span-all"><h2>Product results</h2><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Product</th><th>Submitted</th><th>PASS</th><th>FAIL</th><th>Requires review</th><th>Pass rate</th></tr></thead><tbody>${d.products.map(p=>`<tr><td>${productLabel(p.product)}</td><td>${p.total}</td><td>${p.passed}</td><td>${p.failed}</td><td>${p.held}</td><td>${Number(p.total)?(Number(p.passed)/Number(p.total)*100).toFixed(1)+'%':'N/A'}</td></tr>`).join('')||'<tr><td colspan="6">No data on this day.</td></tr>'}</tbody></table></div></section></div>`;$('#report-filter').onsubmit=e=>{e.preventDefault();const p=formValues(e.target);location.hash='reports?'+new URLSearchParams({date:p.date});};}
reports=async function(q,ticket){const date=q.get('date')||reportToday();let cacheEntry=q.get('cache')==='1'?reportCacheRead(date):null;if(cacheEntry){if(ticket!==S.routeTicket)return;renderDailyReport(reportNormalize(cacheEntry.data,date),cacheEntry,true);return;}const d=reportNormalize(await api('reports',null,{date}),date);if(ticket!==S.routeTicket)return;cacheEntry=reportCacheWrite(date,d);renderDailyReport(d,cacheEntry,false);};
function savedReportRowsHtml(activeDate=''){
    const rows=reportCacheList();
    if(!rows.length)return '<tr><td colspan="8">No saved reports yet. Execute a report first.</td></tr>';
    return rows.flatMap(r=>{
        const products=r.data?.products?.length?r.data.products:[{product:'',total:0,passed:0,failed:0,held:0}];
        return products.map((p,n)=>`<tr class="${r.date===activeDate?'selected-report-row':''}"><td>${n===0?`<strong>${esc(r.date)}</strong><small>${esc(reportExecutedText(r.executed_at))}</small>`:''}</td><td>${p.product?productLabel(p.product):'No product data'}</td><td>${p.total||0}</td><td>${p.passed||0}</td><td>${p.failed||0}</td><td>${p.held||0}</td><td>${Number(p.total)?(Number(p.passed)/Number(p.total)*100).toFixed(1)+'%':'N/A'}</td><td>${n===0?button('Display total','report-cache-open','chart-bar','small',`data-date="${esc(r.date)}"`):''}</td></tr>`);
    }).join('');
}
renderDailyReport=function(d,cacheEntry=null,fromCache=false){const date=d.period?.date||d.period?.from||reportToday();const totals=d.products.reduce((a,p)=>({total:a.total+Number(p.total),passed:a.passed+Number(p.passed),failed:a.failed+Number(p.failed),held:a.held+Number(p.held)}),{total:0,passed:0,failed:0,held:0});const max=Math.max(1,...d.trend.map(x=>Number(x.total)));const top=Math.max(1,...d.defects.map(x=>Number(x.quantity)));const cacheNote=cacheEntry?`${fromCache?'Loaded from cache':'Cached'} · Executed ${reportExecutedText(cacheEntry.executed_at)}`:'Not cached yet';$('#main').innerHTML=`<div class="page-heading"><div><h1>Quality reports</h1><p>Daily submitted first-inspection outcomes and observed defect quantities.</p></div><div class="actions">${button('Saved reports','report-cache-list','database')}</div></div><form id="report-filter" class="filters">${input('date','Submission date',date,'date','required')}<button type="submit" class="btn primary">${icon('player-play')} Execute report</button>${reportCacheRead(date)?button('View cached','report-cache-open','folder-open','',`data-date="${esc(date)}"`):''}<span class="tag">${esc(cacheNote)}</span></form><div class="metrics">${[['Submitted inspections',totals.total],['Pass rate',totals.total?(totals.passed/totals.total*100).toFixed(1)+'%':'N/A'],['Failed inspections',totals.failed],['Requires review',totals.held]].map(([label,value])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">Selected submission day</div></div>`).join('')}</div><div class="report-grid"><section class="report-panel"><div class="section-head"><h2>Inspection trend</h2><div class="legend"><span><i></i>PASS</span><span><i class="red"></i>FAIL</span></div></div>${d.trend.length?`<div class="chart" role="img" aria-label="Submitted first inspection pass and fail counts for ${esc(date)}">${d.trend.map(t=>`<div class="bar-column" title="${t.day}: ${t.passed} pass, ${t.failed} fail"><div class="bar-pair"><div class="bar" style="height:${Number(t.passed)/max*100}%"></div><div class="bar fail" style="height:${Number(t.failed)/max*100}%"></div></div><small>${t.day.slice(5)}</small></div>`).join('')}</div><table><thead><tr><th>Date</th><th>Total</th><th>PASS</th><th>FAIL</th></tr></thead><tbody>${d.trend.map(t=>`<tr><td>${t.day}</td><td>${t.total}</td><td>${t.passed}</td><td>${t.failed}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><p>No first-inspection submissions on this day.</p></div>'}</section><section class="report-panel"><h2>Most frequent defects</h2><p class="muted" style="font-size:12px;margin-top:6px">Quantities recorded on submitted first-inspection units for this day.</p>${d.defects.map(x=>`<div class="horizontal-bar"><span>${esc(x.name)}</span><div><i style="width:${Number(x.quantity)/top*100}%"></i></div><strong>${x.quantity}</strong></div>`).join('')||'<div class="empty"><p>No defects recorded on this day.</p></div>'}</section><section class="report-panel span-all"><h2>Saved Reports</h2><p class="muted" style="font-size:12px;margin-top:6px">Saved daily reports that have been executed on this browser.</p><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Report date</th><th>Product</th><th>Submitted</th><th>PASS</th><th>FAIL</th><th>Requires review</th><th>Pass rate</th><th></th></tr></thead><tbody>${savedReportRowsHtml(date)}</tbody></table></div></section></div>`;$('#report-filter').onsubmit=e=>{e.preventDefault();const p=formValues(e.target);location.hash='reports?'+new URLSearchParams({date:p.date});};};
const renderDailyReportWithSavedReportsTable=renderDailyReport;
renderDailyReport=function(...args){renderDailyReportWithSavedReportsTable(...args);const savedButton=document.querySelector('.page-heading [data-action="report-cache-list"]');savedButton?.remove();const actions=document.querySelector('.page-heading .actions');if(actions&&!actions.children.length)actions.remove();};
function reportTotals(products=[]){
    return products.reduce((a,p)=>({total:a.total+Number(p.total||0),passed:a.passed+Number(p.passed||0),failed:a.failed+Number(p.failed||0),held:a.held+Number(p.held||0)}),{total:0,passed:0,failed:0,held:0});
}
function reportRate(passed,total){return Number(total)?(Number(passed)/Number(total)*100).toFixed(1)+'%':'N/A';}
const reportSnapshotCache=new Map();
function reportCacheId(row){return row?`${row.date}:${row.version}`:'';}
function rememberReportSnapshot(snapshot){
    if(snapshot?.report) reportSnapshotCache.set(reportCacheId(snapshot.report),snapshot);
}
function rememberSavedReportRows(rows=[]){
    rows.forEach(row=>{
        if(row.snapshot){
            row.snapshot.report={...row,products:undefined,snapshot:undefined};
            reportSnapshotCache.set(reportCacheId(row),row.snapshot);
        }
    });
}
function savedReportServerRows(rows=[],activeId=0){
    if(!rows.length)return '<tr><td colspan="9">No saved reports yet. Execute a report first.</td></tr>';
    return rows.flatMap(r=>{
        const products=r.products?.length?r.products:[{product:'',total:0,passed:0,failed:0,held:0}];
        return products.map((p,n)=>`<tr class="${Number(r.id)===Number(activeId)?'selected-report-row':''}"><td>${n===0?`<strong>${esc(r.date)} v${Number(r.version)}</strong><small>${esc(reportExecutedText(r.executed_at))}</small><small>${esc(r.executed_by_name||'')}</small>`:''}</td><td>${p.product?productLabel(p.product):'No product data'}</td><td>${Number(p.total||0)}</td><td>${Number(p.passed||0)}</td><td>${Number(p.failed||0)}</td><td>${Number(p.held||0)}</td><td>${reportRate(p.passed,p.total)}</td><td>${n===0?(r.has_newer_changes?status('held').replace('Requires review','Newer changes'):status('pass').replace('PASS','Current')):''}</td><td>${n===0?`<button type="button" class="btn small" data-report-open data-date="${esc(r.date)}" data-version="${Number(r.version)}">${icon('eye')} Display total</button>`:''}</td></tr>`);
    }).join('');
}
function renderSharedDailyReport(snapshot,date,savedRows=[]){
    rememberSavedReportRows(savedRows);
    rememberReportSnapshot(snapshot);
    const d=snapshot||{period:{date},stats:{},trend:[],defects:[],products:[]};
    const products=d.products||[];
    const totals=reportTotals(products);
    const max=Math.max(1,...(d.trend||[]).map(x=>Number(x.total||0)));
    const top=Math.max(1,...(d.defects||[]).map(x=>Number(x.quantity||0)));
    const report=d.report||null;
    const note=report?`${report.has_newer_changes?'Saved version has newer inspection changes':'Saved version is current'} - executed ${reportExecutedText(report.executed_at)}`:'No saved report loaded for this day';
    $('#main').innerHTML=`<div class="page-heading"><div><h1>Quality reports</h1><p>Daily submitted first-inspection outcomes and observed defect quantities.</p></div></div><form id="report-filter" class="filters">${input('date','Submission date',date,'date','required')}<button type="submit" class="btn">${icon('folder-open')} Load saved</button><button type="button" class="btn primary" id="report-execute">${icon('player-play')} Execute report</button><span class="tag">${esc(note)}</span></form><div class="metrics">${[['Submitted inspections',totals.total],['Pass rate',reportRate(totals.passed,totals.total)],['Failed inspections',totals.failed],['Requires review',totals.held]].map(([label,value])=>`<div class="metric"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-foot">${report?'Displayed saved report':'Execute to save this day'}</div></div>`).join('')}</div><div class="report-grid"><section class="report-panel"><div class="section-head"><h2>Inspection trend</h2><div class="legend"><span><i></i>PASS</span><span><i class="red"></i>FAIL</span></div></div>${(d.trend||[]).length?`<div class="chart" role="img" aria-label="Submitted first inspection pass and fail counts for ${esc(date)}">${d.trend.map(t=>`<div class="bar-column" title="${esc(t.day)}: ${Number(t.passed||0)} pass, ${Number(t.failed||0)} fail"><div class="bar-pair"><div class="bar" style="height:${Number(t.passed||0)/max*100}%"></div><div class="bar fail" style="height:${Number(t.failed||0)/max*100}%"></div></div><small>${esc(String(t.day||'').slice(5))}</small></div>`).join('')}</div><table><thead><tr><th>Date</th><th>Total</th><th>PASS</th><th>FAIL</th></tr></thead><tbody>${d.trend.map(t=>`<tr><td>${esc(t.day)}</td><td>${Number(t.total||0)}</td><td>${Number(t.passed||0)}</td><td>${Number(t.failed||0)}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><p>No saved report displayed for this day.</p></div>'}</section><section class="report-panel"><h2>Most frequent defects</h2><p class="muted" style="font-size:12px;margin-top:6px">Quantities recorded on submitted first-inspection units for this day.</p>${(d.defects||[]).map(x=>`<div class="horizontal-bar"><span>${esc(x.name)}</span><div><i style="width:${Number(x.quantity||0)/top*100}%"></i></div><strong>${Number(x.quantity||0)}</strong></div>`).join('')||'<div class="empty"><p>No defects recorded in the displayed report.</p></div>'}</section><section class="report-panel span-all"><h2>Saved Reports</h2><p class="muted" style="font-size:12px;margin-top:6px">Shared saved daily reports from Turso. Displaying one does not execute a new report.</p><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Report date</th><th>Product</th><th>Submitted</th><th>PASS</th><th>FAIL</th><th>Requires review</th><th>Pass rate</th><th>Status</th><th></th></tr></thead><tbody>${savedReportServerRows(savedRows,report?.id||0)}</tbody></table></div></section></div>`;
    $('#report-filter').onsubmit=e=>{e.preventDefault();const p=formValues(e.target);location.hash='reports?'+new URLSearchParams({date:p.date});};
    $('#report-execute').onclick=async e=>{
        const done=buttonBusy(e.currentTarget,'Executing');
        try{
            const p=formValues($('#report-filter'));
            const fresh=await api('report_execute',{date:p.date},{},{timeoutMs:120000});
            toast('Report saved.');
            renderSharedDailyReport(fresh,p.date,[{...fresh.report,snapshot:fresh},...savedRows.filter(r=>Number(r.id)!==Number(fresh.report?.id))]);
        }catch(err){toast(err.message,true);}
        finally{done();}
    };
    $$('[data-report-open]').forEach(b=>b.onclick=async()=>{
        const cached=reportSnapshotCache.get(`${b.dataset.date}:${b.dataset.version}`);
        if(!cached){toast('Saved report is not loaded yet. Load the report list again.',true);return;}
        history.replaceState(null,'','#reports?'+new URLSearchParams({date:b.dataset.date,version:b.dataset.version}));
        S.route=currentRoute();
        renderSharedDailyReport(cached,b.dataset.date,savedRows);
    });
}
reports=async function(q,ticket){
    const date=q.get('date')||reportToday();
    const params={date};
    if(q.get('version'))params.version=q.get('version');
    const d=await api('reports',null,params,{timeoutMs:60000});
    if(ticket!==S.routeTicket)return;
    rememberSavedReportRows(d.saved?.reports||[]);
    rememberReportSnapshot(d.snapshot);
    renderSharedDailyReport(d.snapshot,date,d.saved?.reports||[]);
};
