function specDialog(){const f=modal('Add approved specification',`<p>Create a new specification revision from an approved source. Existing inspection limits will stay unchanged.</p><div class="field-grid two">${select('product','Inspection type',[{value:'cpetpe',label:'CPE / TPE'},{value:'hdpe',label:'HDPE'}],'hdpe','required')}${input('reference','Specification reference','','text','required')}${select('glove_type','Glove type',['HD120'],'HD120','required')}${select('size','Size',['XXS','XS','S','M','L','XL','XXL','FS'],'FS','required')}${input('product_type','Product type','HDPE','text','required')}<label class="field span-all"><span>Approval reference / source *</span><textarea name="source" required placeholder="Approved document number, revision, date and authority"></textarea></label></div><div class="divider"></div><div id="limit-inputs"></div>`,`<button type="button" class="btn" data-action="close-dialog">Cancel</button><button type="submit" class="btn primary">Create specification</button>`,true);const populate=()=>{const p=f.elements.product.value;f.elements.glove_type.innerHTML=options(S.meta.products[p].references['Glove Type'],p==='hdpe'?'HD120':'');f.elements.product_type.value=p==='hdpe'?'HDPE':'';$('#limit-inputs').innerHTML=`<table><thead><tr><th>Measurement</th><th>Min</th><th>Nominal</th><th>Max</th><th>N/A</th></tr></thead><tbody>${S.meta.products[p].metrics.filter(m=>m.key!=='thickness').map(m=>`<tr><td>${m.label}</td>${['min','nominal','max'].map(k=>`<td><input type="number" step="any" min="0" name="limit_${m.key}_${k}" aria-label="${m.label} ${k}"></td>`).join('')}<td><input type="checkbox" name="limit_${m.key}_na" aria-label="${m.label} not applicable"></td></tr>`).join('')}</tbody></table>`;};f.elements.product.onchange=populate;populate();f.onsubmit=async e=>{e.preventDefault();const data=formValues(f);data.limits={};S.meta.products[data.product].metrics.filter(m=>m.key!=='thickness').forEach(m=>{data.limits[m.key]={};['min','max','nominal'].forEach(k=>data.limits[m.key][k]=data['limit_'+m.key+'_'+k]||null);data.limits[m.key].na=f.elements['limit_'+m.key+'_na'].checked;});try{await api('specification',data);closeModal();toast('Approved specification created.');await route();}catch(err){modalError(err);}};}
