masters=async function(ticket){S.meta=await api('bootstrap');if(ticket!==S.routeTicket)return;$('#main').innerHTML=`<div class="page-heading"><div><h1>Specification master</h1><p>Approved product limits used automatically by inspection type, glove type and size.</p></div>${S.user.role==='admin'?button('Add specification','new-spec','plus','primary'):''}</div><div class="filters"><label class="search">${icon('search')}<input id="spec-search" type="search" placeholder="Search glove, reference or size" aria-label="Search specifications"></label><select id="spec-product" aria-label="Specification product">${options([{value:'cpetpe',label:'CPE / TPE'},{value:'hdpe',label:'HDPE'}],'','All products')}</select><span class="tag">${S.meta.specifications.length} active references</span></div><div class="notice neutral">${icon('ruler-measure')}<div>New and draft inspections automatically look up this table. Deleted specifications are hidden from future lookup, while completed records keep their saved snapshot.</div></div><div class="surface" id="spec-results"></div>`;const refresh=()=>{const search=$('#spec-search').value.toLowerCase(),p=$('#spec-product').value;const rows=S.meta.specifications.filter(s=>(!p||s.product===p)&&`${s.reference_name} ${s.glove_type} ${s.size} ${s.product_type}`.toLowerCase().includes(search));$('#spec-results').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Glove type</th><th>Reference</th><th>Product type</th><th>Size</th><th>Revision</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr><td><strong>${esc(s.glove_type)}</strong><small>${productLabel(s.product)}</small></td><td>${esc(s.reference_name)}</td><td>${esc(s.product_type)}</td><td>${esc(sizeLabel(s))}</td><td><span class="tag">${esc(s.revision)}</span></td><td><div class="record-actions">${button('View','view-spec','ruler-measure','small',`data-id="${esc(s.id)}"`)}${S.user.role==='admin'?button('Edit','edit-spec','edit','small',`data-id="${esc(s.id)}"`)+button('Delete','delete-spec','trash','small danger',`data-id="${esc(s.id)}" data-label="${esc(s.glove_type+' '+s.size+' '+s.reference_name)}"`):''}</div></td></tr>`).join('')||'<tr><td colspan="6">No matching specification.</td></tr>'}</tbody></table></div>`;};$('#spec-search').oninput=refresh;$('#spec-product').onchange=refresh;refresh();};

viewSpec=async function(id){const s=await api('spec',null,{id});modal('Specification limits',`<div class="section-head"><div><h3>${esc(s.glove_type)} · ${esc(sizeLabel(s))}</h3><p>${esc(s.reference)}</p></div><span class="tag">${esc(s.product_type)}</span></div><table><thead><tr><th>Measurement</th><th>Minimum</th><th>Nominal</th><th>Maximum</th></tr></thead><tbody>${S.meta.products[s.product].metrics.filter(m=>m.key!=='thickness').map(m=>{const l=s.limits[m.key]||{};return `<tr><td>${m.label}${m.unit?' ('+m.unit+')':''}</td><td>${l.na?'N/A':l.min??'Not supplied'}</td><td>${l.na?'N/A':l.nominal??'Not supplied'}</td><td>${l.na?'N/A':l.max??'Not supplied'}</td></tr>`;}).join('')}</tbody></table><div class="info-band">${icon('file-certificate')}<span>${esc(s.source)}<br>Revision: ${esc(s.revision)}</span></div>`,`${S.user.role==='admin'?button('Edit specification','edit-spec','edit','primary',`data-id="${esc(s.id)}"`):''}${button('Close','close-dialog',null)}`);};

specDialog=async function(id=''){const existing=id?await api('spec',null,{id}):null;const product=existing?.product||'hdpe';const f=modal(existing?'Edit specification':'Add approved specification',`<p>${existing?'Update the active master limits used by future lookups. Existing submitted inspection snapshots are not rewritten.':'Create a new active specification reference from an approved source.'}</p><div class="field-grid two">${select('product','Inspection type',[{value:'cpetpe',label:'CPE / TPE'},{value:'hdpe',label:'HDPE'}],product,existing?'disabled required':'required')}${existing?`<input type="hidden" name="id" value="${esc(existing.id)}">`:''}${input('reference','Specification reference',existing?.reference||'','text','required')}${select('glove_type','Glove type',S.meta.products[product].references['Glove Type'],existing?.glove_type||(product==='hdpe'?'HD120':''),'required')}${select('size','Size',S.meta.products[product].references.Size,existing?.size||(product==='hdpe'?'FS':'S'),'required')}${input('product_type','Product type',existing?.product_type||(product==='hdpe'?'HDPE':''),'text','required')}<label class="field span-all"><span>Approval reference / source *</span><textarea name="source" required placeholder="Approved document number, revision, date and authority">${esc(existing?.source||'')}</textarea></label></div><div class="divider"></div><div id="limit-inputs"></div>`,`<button type="button" class="btn" data-action="close-dialog">Cancel</button><button type="submit" class="btn primary">${existing?'Save changes':'Create specification'}</button>`,true);const populate=()=>{const p=f.elements.product.value;const source=existing&&p===existing.product?existing:null;f.elements.glove_type.innerHTML=options(S.meta.products[p].references['Glove Type'],source?.glove_type||(p==='hdpe'?'HD120':''));f.elements.size.innerHTML=options(S.meta.products[p].references.Size,source?.size||(p==='hdpe'?'FS':'S'));if(!source)f.elements.product_type.value=p==='hdpe'?'HDPE':'';$('#limit-inputs').innerHTML=`<table><thead><tr><th>Measurement</th><th>Min</th><th>Nominal</th><th>Max</th><th>N/A</th></tr></thead><tbody>${S.meta.products[p].metrics.filter(m=>m.key!=='thickness').map(m=>{const l=source?.limits?.[m.key]||{};return `<tr><td>${esc(m.label)}</td>${['min','nominal','max'].map(k=>`<td><input type="number" step="any" min="0" name="limit_${m.key}_${k}" value="${esc(l[k]??'')}" aria-label="${esc(m.label)} ${k}"></td>`).join('')}<td><input type="checkbox" name="limit_${m.key}_na" ${l.na?'checked':''} aria-label="${esc(m.label)} not applicable"></td></tr>`;}).join('')}</tbody></table>`;};f.elements.product.onchange=populate;populate();f.onsubmit=async e=>{e.preventDefault();const done=buttonBusy($('button[type=submit]',f),existing?'Saving':'Creating');const data=formValues(f);data.product=existing?.product||data.product;data.id=existing?.id||data.id||'';data.limits={};S.meta.products[data.product].metrics.filter(m=>m.key!=='thickness').forEach(m=>{data.limits[m.key]={};['min','max','nominal'].forEach(k=>data.limits[m.key][k]=data['limit_'+m.key+'_'+k]||null);data.limits[m.key].na=f.elements['limit_'+m.key+'_na'].checked;});try{await api('specification',data);closeModal();toast(existing?'Specification updated.':'Approved specification created.');await route();}catch(err){modalError(err);done();}};};

function deleteSpecDialog(id,label='this specification'){const f=modal('Delete specification',`<p>This removes ${esc(label)} from future automatic lookup. Existing submitted records keep their saved specification snapshot.</p><div class="notice error">${icon('alert-circle')}<div><strong>Deactivate this master reference?</strong>You can add it again later if needed.</div></div>`,`<button type="button" class="btn" data-action="close-dialog">Cancel</button><button type="submit" class="btn danger">${icon('trash')} Delete specification</button>`);f.onsubmit=async e=>{e.preventDefault();const done=buttonBusy($('button[type=submit]',f),'Deleting');try{await api('delete_spec',{id});closeModal();toast('Specification deleted.');await route();}catch(err){modalError(err);done();}};}

function recordMeasurementCell(i,m,n){const limit=i.spec?.limits?.[m.key]||{},values=i.data.measurements?.[m.key]||[],required=n<m.samples;if(!required||(limit.na&&i.data.section_flags?.[m.section]!=='pass'))return`<td class="measurement-cell muted-cell">--</td>`;const v=values[n],r=qrexEffectiveSectionResult(i,m.section,readingResult(v,limit));return `<td class="measurement-cell ${r==='fail'?'failed':''}"><div class="readonly-reading">${esc(v??'--')}<small>${esc(m.unit||'')}</small></div></td>`;}
function recordMeasurementLabel(m){return typeof measurementDisplayLabel==='function'?measurementDisplayLabel(m):m.key==='thickness'?'Thickness':m.label;}
function recordMeasurementDisposition(i,m){const result=qrexEffectiveSectionResult(i,m.section,i.evaluation?.checks?.[m.key]?.result||'pending');return status(result==='na'?'pending':result);}
function recordMeasurementGroupTable(i,title,metrics){if(!metrics.length)return'';const maxSamples=Math.max(...metrics.map(m=>m.samples));const singleReading=maxSamples===1;return `<section class="measurement-group-panel record-measurement-panel"><div class="measurement-group-head"><h3>${esc(title)}</h3><span class="muted">${metrics.length} field${metrics.length===1?'':'s'}</span></div><div class="measurement-grid-wrap compact-measurement-wrap record-measurement-grid"><table class="measurement-grid compact-measurement-grid transposed-measurement-grid ${singleReading?'single-transposed-measurement-grid':''}" aria-label="${esc(title)} saved readings by measurement"><thead><tr><th class="sticky-sample">Measurement</th>${Array.from({length:maxSamples},(_,n)=>`<th>${singleReading?'Reading':String(n+1).padStart(2,'0')}</th>`).join('')}<th class="disposition-col">Disposition</th></tr></thead><tbody>${metrics.map(m=>`<tr><th class="sticky-sample measurement-row-label"><span>${esc(recordMeasurementLabel(m))}</span><small>${esc(measurementLimitSummary(i,m))}</small></th>${Array.from({length:maxSamples},(_,n)=>recordMeasurementCell(i,m,n)).join('')}<td class="measurement-disposition-cell">${recordMeasurementDisposition(i,m)}</td></tr>`).join('')}</tbody></table></div></section>`;}
function recordMeasurementsMatrix(i,metricKey=''){const metrics=S.meta.products[i.product].metrics.filter(m=>m.section==='measurements'&&(!metricKey||m.key===metricKey));if(!metrics.length)return'<p class="muted">No measurement readings configured.</p>';if(metricKey)return recordMeasurementGroupTable(i,recordMeasurementLabel(metrics[0]),metrics);const weightMetrics=metrics.filter(m=>m.key==='weight');const thicknessMetrics=metrics.filter(m=>m.key==='thickness');const dimensionMetrics=metrics.filter(m=>!['weight','thickness'].includes(m.key));return `<div class="measurement-group-stack record-measurement-groups"><div class="measurement-top-grid">${recordMeasurementGroupTable(i,'Weight',weightMetrics)}${recordMeasurementGroupTable(i,'Thickness',thicknessMetrics)}</div>${recordMeasurementGroupTable(i,'Dimensions',dimensionMetrics)}</div>`;}
function recordDetailSection(id,title,state,body,actions=''){return `<section class="record-detail-section" id="${id}"><div class="section-head"><h3>${esc(title)}</h3><div class="actions">${actions}${status(state)}</div></div>${body}</section>`;}
record=async function(q,ticket){const i=await api('inspection',null,{id:q.get('id')});if(ticket!==S.routeTicket)return;S.record=i;const e=i.evaluation;const supervisor=['admin','supervisor'].includes(S.user.role);const definitions=S.meta.products[i.product];const orderContext={'Factory':i.common.factory,'Plant':i.common.plant,'Item number':i.common.item_no,'Lot number':i.common.lot_no,'Customer':i.common.customer,'Country':i.common.country,'Brand':i.common.brand,'Product type':i.common.product_type,'Colour':i.common.colour};const defectBody=i.data.defects.length?`<table><thead><tr><th>Category</th><th>Defect</th><th>Quantity</th></tr></thead><tbody>${i.data.defects.map(d=>`<tr><td>${esc(d.category)}</td><td>${esc(d.name)}</td><td>${d.quantity}</td></tr>`).join('')}</tbody></table>`:`<div class="info-band">${icon('circle-check')}<span>No failed visual defects recorded.</span></div>`;const testBody=`${compactResultList(definitions.tests.map(test=>{const values=i.data.tests[test.key]||[];const result=qrexEffectiveSectionResult(i,'tests',i.evaluation?.checks?.[test.key]?.result||(values.includes('fail')?'fail':values.includes('pass')?'pass':'na'));return [test.label,values.length?values.map(v=>labels[v]||v).join(' / '):'N/A',result];}))}${definitions.metrics.filter(m=>m.section==='tests').map(m=>`<div id="record-${m.key}" class="record-metric">${recordMetricTable(i,m)}</div>`).join('')}`;const measurementBody=recordMeasurementsMatrix(i);const nav=[['record-unit','Unit information'],['record-defects','Visual inspection'],['record-tests','Performance tests'],['record-measurements','Measurements'],['record-remarks','Remarks']];$('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">Inspection record · QI-${String(i.id).padStart(5,'0')}</p><h1>SO ${esc(i.so_number)} / ${esc(i.unit_label)}</h1><p>${productLabel(i.product)} · ${esc(i.glove_type)} · Size ${esc(sizeLabel(i))} · ${dateText(i.updated_at)}</p></div><div class="actions">${status(i.state)}${i.editable?`<a class="btn primary" href="#inspection?id=${i.id}">${icon('edit')} Continue draft</a>`:''}${supervisor&&i.state==='submitted'?button('Verify inspection','verify','user-check','primary'):''}${supervisor&&i.state!=='draft'?button('Reopen for editing','reopen','edit'):''}${button('Print','print','printer')}</div></div><div class="record-dashboard"><section class="form-surface"><div class="form-section-head"><div><h2>Inspection result</h2><p>Record version ${i.version}</p></div>${status(i.result)}</div><div class="form-content"><div class="review-summary"><div><h2>${e.passed} passed <span class="muted" style="font-size:15px;font-weight:400">/ ${e.failed} failed checks</span></h2><p>${e.missing.length?e.missing.length+' incomplete entries':'All required inspection entries recorded'}</p></div></div>${compactResultList([['Workflow',labels[i.state],i.state],['Final disposition',labels[i.result],i.result],['Specification',i.spec?.reference||'Not available',i.spec?'pass':'hold'],['Revision',i.spec?.revision||'Not available','']])}</div></section><section class="form-surface"><div class="form-section-head"><h2>Attention & verification</h2>${status(i.state)}</div><div class="form-content">${e.issues.length?e.issues.map(issue=>recordIssueLink(i,issue)).join(''):`<div class="info-band">${icon('circle-check')}<span>No failed checks recorded.</span></div>`}<div class="divider"></div><h3>Verification history</h3>${i.verifications.length?i.verifications.map(v=>`<div class="verification-card"><div class="section-head"><strong>${esc(v.reviewer)}</strong>${status(v.decision)}</div><p>${esc(v.notes)}</p><small>${dateText(v.created_at)} · Inspection version ${v.inspection_version}</small></div>`).join(''):'<p class="muted" style="font-size:12px;margin-top:12px">This inspection has not been verified.</p>'}</div></section></div><section class="form-surface record-detail-surface"><div class="record-detail-head"><div><h2>Inspection details</h2><p>Scroll down to review every saved section.</p></div>${supervisor&&i.state==='draft'?button('Assign approved specification','apply-spec','ruler-measure','small'):''}</div><nav class="record-detail-nav" aria-label="Inspection detail sections">${nav.map(([id,label])=>`<button type="button" data-action="record-scroll" data-target="${id}">${esc(label)}</button>`).join('')}</nav><div class="record-detail-stack">${recordDetailSection('record-unit','Unit information',e.sections.information,recordFields(orderContext))}${recordDetailSection('record-defects','Visual inspection',e.sections.defects,defectBody+(i.data.fields.defect_remarks?`<p class="muted record-note">${esc(i.data.fields.defect_remarks)}</p>`:''))}${recordDetailSection('record-tests','Performance tests',e.sections.tests,testBody)}${recordDetailSection('record-measurements','Measurements',e.sections.measurements,measurementBody)}${recordDetailSection('record-remarks','Inspection remarks',i.data.fields.remarks?'pass':'pending',`<p>${esc(i.data.fields.remarks||'No remarks recorded.')}</p>`)}</div></section>`;};

function recordFields(values){const label=k=>String(k).toLowerCase()==='inspection status'?'Inspection Count':k;return `<dl class="record-field-grid">${Object.entries(values).map(([k,v])=>`<div><dt>${esc(label(k))}</dt><dd>${esc(v||'Not recorded')}</dd></div>`).join('')}</dl>`;}
function recordPanel(title,state,body,open=true,id=''){return `<details class="record-panel" ${id?`id="${id}"`:''} ${open?'open':''}><summary><span>${esc(title)}</span>${status(state)}</summary><div class="record-panel-body">${body}</div></details>`;}
function compactResultList(items){return `<div class="compact-result-list">${items.map(([name,value,result])=>`<div><span>${esc(name==='Workflow'?'Form Status':name)}</span><strong>${esc(value||'Not recorded')}</strong>${result?status(result):''}</div>`).join('')}</div>`;}
record=async function(q,ticket){const i=await api('inspection',null,{id:q.get('id')});if(ticket!==S.routeTicket)return;S.record=i;const e=i.evaluation;const supervisor=['admin','supervisor'].includes(S.user.role);const definitions=S.meta.products[i.product];const orderInfo={'Sales order':i.so_number,'SO item':i.so_item_no,'Product':productLabel(i.product),'Glove type / code':i.glove_type,'Size':sizeLabel(i),'Unit':i.unit_label,'Factory':i.common.factory,'Plant':i.common.plant,'Customer':i.common.customer,'Country':i.common.country,'Item number':i.common.item_no,'Lot number':i.common.lot_no,'Brand':i.common.brand,'Colour':i.common.colour,'Product type':i.common.product_type};const fields=Object.fromEntries(Object.entries(i.data.fields).filter(([k])=>!['remarks','defect_remarks'].includes(k)).map(([k,v])=>[k.replaceAll('_',' '),v]));const defectBody=i.data.defects.length?`<table><thead><tr><th>Category</th><th>Defect</th><th>Quantity</th></tr></thead><tbody>${i.data.defects.map(d=>`<tr><td>${esc(d.category)}</td><td>${esc(d.name)}</td><td>${d.quantity}</td></tr>`).join('')}</tbody></table>`:'<div class="info-band">'+icon('circle-check')+'<span>No failed visual defects recorded.</span></div>';const testBody=`${compactResultList(definitions.tests.map(test=>{const values=i.data.tests[test.key]||[];const result=qrexEffectiveSectionResult(i,'tests',i.evaluation?.checks?.[test.key]?.result||(values.includes('fail')?'fail':values.includes('pass')?'pass':'na'));return [test.label,values.length?values.map(v=>labels[v]||v).join(' / '):'N/A',result];}))}${definitions.metrics.filter(m=>m.section==='tests').map(m=>`<div id="record-${m.key}" class="record-metric">${recordMetricTable(i,m)}</div>`).join('')}`;const measurementBody=definitions.metrics.filter(m=>m.section==='measurements').map(m=>`<details class="record-metric" id="record-${m.key}"><summary>${esc(m.label)} ${status(e.checks[m.key]?.result||'pending')}</summary>${recordMetricTable(i,m)}</details>`).join('');$('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">Inspection record · QI-${String(i.id).padStart(5,'0')}</p><h1>SO ${esc(i.so_number)} / ${esc(i.unit_label)}</h1><p>${productLabel(i.product)} · ${esc(i.glove_type)} · Size ${esc(sizeLabel(i))} · ${dateText(i.updated_at)}</p></div><div class="actions">${status(i.state)}${i.editable?`<a class="btn primary" href="#inspection?id=${i.id}">${icon('edit')} Continue draft</a>`:''}${supervisor&&i.state==='submitted'?button('Verify inspection','verify','user-check','primary'):''}${supervisor&&i.state!=='draft'?button('Reopen for editing','reopen','edit'):''}${button('Print','print','printer')}</div></div><div class="record-dashboard"><section class="form-surface"><div class="form-section-head"><div><h2>Inspection result</h2><p>Record version ${i.version}</p></div>${status(i.result)}</div><div class="form-content"><div class="review-summary"><div><h2>${e.passed} passed <span class="muted" style="font-size:15px;font-weight:400">/ ${e.failed} failed checks</span></h2><p>${e.missing.length?e.missing.length+' incomplete entries':'All required inspection entries recorded'}</p></div></div>${compactResultList([['Workflow',labels[i.state],i.state],['Final disposition',labels[i.result],i.result],['Specification',i.spec?.reference||'Not available',i.spec?'pass':'hold'],['Revision',i.spec?.revision||'Not available','']])}</div></section><section class="form-surface"><div class="form-section-head"><h2>Attention & verification</h2>${status(i.state)}</div><div class="form-content">${e.issues.length?e.issues.map(issue=>recordIssueLink(i,issue)).join(''):`<div class="info-band">${icon('circle-check')}<span>No failed checks recorded.</span></div>`}<div class="divider"></div><h3>Verification history</h3>${i.verifications.length?i.verifications.map(v=>`<div class="verification-card"><div class="section-head"><strong>${esc(v.reviewer)}</strong>${status(v.decision)}</div><p>${esc(v.notes)}</p><small>${dateText(v.created_at)} · Inspection version ${v.inspection_version}</small></div>`).join(''):'<p class="muted" style="font-size:12px;margin-top:12px">This inspection has not been verified.</p>'}</div></section></div><section class="form-surface"><div class="form-section-head"><div><h2>Inspection details</h2><p>Grouped from the submitted template and saved records.</p></div>${supervisor&&i.state==='draft'?button('Assign approved specification','apply-spec','ruler-measure','small'):''}</div><div class="form-content record-detail-grid">${recordPanel('Unit information',e.sections.information,recordFields({...orderInfo,...fields}),true)}${recordPanel('Visual inspection',e.sections.defects,defectBody+(i.data.fields.defect_remarks?`<p class="muted record-note">${esc(i.data.fields.defect_remarks)}</p>`:''),true,'record-defects')}${recordPanel('Performance tests',e.sections.tests,testBody,false,'record-tests')}${recordPanel('Measurements',e.sections.measurements,measurementBody,false,'record-measurements')}${recordPanel('Inspection remarks',i.data.fields.remarks?'pass':'pending',`<p>${esc(i.data.fields.remarks||'No remarks recorded.')}</p>`,false)}<details class="record-panel" id="audit-details"><summary><span>Audit trail</span>${icon('history')}</summary><div class="record-panel-body"><div id="audit-body" class="muted">Open to load record history.</div></div></details></div></section>`;$('#audit-details').ontoggle=async event=>{if(!event.target.open||event.target.dataset.loaded)return;try{const a=await api('audit',null,{id:i.id});$('#audit-body').innerHTML=`<div class="timeline">${a.rows.map(r=>`<div class="timeline-item"><strong>${esc(r.action.replaceAll('_',' '))}</strong><p>${esc(r.actor||'System')} · ${esc(r.created_at)}${r.details.notes?'<br>'+esc(r.details.notes):''}</p><details><summary style="font-size:11px;color:var(--muted);cursor:pointer;margin-top:6px">Change details</summary><pre class="data-change">${esc(JSON.stringify(r.details,null,2))}</pre></details></div>`).join('')}</div>`;event.target.dataset.loaded='1';}catch(err){$('#audit-body').textContent=err.message;}};};

function recordDetailSection(id,title,state,body){return `<section class="record-detail-section" id="${id}"><div class="section-head"><h3>${esc(title)}</h3>${status(state)}</div>${body}</section>`;}
recordDetailSection=function(id,title,state,body,actions=''){return `<section class="record-detail-section" id="${id}"><div class="section-head"><h3>${esc(title)}</h3><div class="actions">${actions}${status(state)}</div></div>${body}</section>`;};
record=async function(q,ticket){const i=await api('inspection',null,{id:q.get('id')});if(ticket!==S.routeTicket)return;S.record=i;const e=i.evaluation;const supervisor=['admin','supervisor'].includes(S.user.role);const definitions=S.meta.products[i.product];const orderContext={'Factory':i.common.factory,'Plant':i.common.plant,'Item number':i.common.item_no,'Lot number':i.common.lot_no,'Customer':i.common.customer,'Country':i.common.country,'Brand':i.common.brand,'Product type':i.common.product_type,'Colour':i.common.colour};const defectBody=i.data.defects.length?`<table><thead><tr><th>Category</th><th>Defect</th><th>Quantity</th></tr></thead><tbody>${i.data.defects.map(d=>`<tr><td>${esc(d.category)}</td><td>${esc(d.name)}</td><td>${d.quantity}</td></tr>`).join('')}</tbody></table>`:`<div class="info-band">${icon('circle-check')}<span>No failed visual defects recorded.</span></div>`;const testBody=`${compactResultList(definitions.tests.map(test=>{const values=i.data.tests[test.key]||[];const result=qrexEffectiveSectionResult(i,'tests',i.evaluation?.checks?.[test.key]?.result||(values.includes('fail')?'fail':values.includes('pass')?'pass':'na'));return [test.label,values.length?values.map(v=>labels[v]||v).join(' / '):'N/A',result];}))}${definitions.metrics.filter(m=>m.section==='tests').map(m=>`<div id="record-${m.key}" class="record-metric">${recordMetricTable(i,m)}</div>`).join('')}`;const measurementBody=recordMeasurementsMatrix(i);const nav=[['record-unit','Unit information'],['record-defects','Visual inspection'],['record-tests','Performance tests'],['record-measurements','Measurements'],['record-remarks','Remarks']];$('#main').innerHTML=`<div class="page-heading"><div><p class="eyebrow">Inspection record · QI-${String(i.id).padStart(5,'0')}</p><h1>SO ${esc(i.so_number)} / ${esc(i.unit_label)}</h1><p>${productLabel(i.product)} · ${esc(i.glove_type)} · Size ${esc(sizeLabel(i))} · ${dateText(i.updated_at)}</p></div><div class="actions">${status(i.state)}${i.editable?`<a class="btn primary" href="#inspection?id=${i.id}">${icon('edit')} Continue draft</a>`:''}${supervisor&&i.state==='submitted'?button('Verify inspection','verify','user-check','primary'):''}${supervisor&&i.state!=='draft'?button('Reopen for editing','reopen','edit'):''}${button('Print','print','printer')}</div></div><div class="record-dashboard"><section class="form-surface"><div class="form-section-head"><div><h2>Inspection result</h2><p>Record version ${i.version}</p></div>${status(i.result)}</div><div class="form-content"><div class="review-summary"><div><h2>${e.passed} passed <span class="muted" style="font-size:15px;font-weight:400">/ ${e.failed} failed checks</span></h2><p>${e.missing.length?e.missing.length+' incomplete entries':'All required inspection entries recorded'}</p></div></div>${compactResultList([['Workflow',labels[i.state],i.state],['Final disposition',labels[i.result],i.result],['Specification',i.spec?.reference||'Not available',i.spec?'pass':'hold'],['Revision',i.spec?.revision||'Not available','']])}</div></section><section class="form-surface"><div class="form-section-head"><h2>Attention & verification</h2>${status(i.state)}</div><div class="form-content">${e.issues.length?e.issues.map(issue=>recordIssueLink(i,issue)).join(''):`<div class="info-band">${icon('circle-check')}<span>No failed checks recorded.</span></div>`}<div class="divider"></div><h3>Verification history</h3>${i.verifications.length?i.verifications.map(v=>`<div class="verification-card"><div class="section-head"><strong>${esc(v.reviewer)}</strong>${status(v.decision)}</div><p>${esc(v.notes)}</p><small>${dateText(v.created_at)} · Inspection version ${v.inspection_version}</small></div>`).join(''):'<p class="muted" style="font-size:12px;margin-top:12px">This inspection has not been verified.</p>'}</div></section></div><section class="form-surface record-detail-surface"><div class="record-detail-head"><div><h2>Inspection details</h2><p>Scroll down to review every saved section.</p></div>${supervisor&&i.state==='draft'?button('Assign approved specification','apply-spec','ruler-measure','small'):''}</div><nav class="record-detail-nav" aria-label="Inspection detail sections">${nav.map(([id,label])=>`<button type="button" data-action="record-scroll" data-target="${id}">${esc(label)}</button>`).join('')}</nav><div class="record-detail-stack">${recordDetailSection('record-unit','Unit information',e.sections.information,recordFields(orderContext))}${recordDetailSection('record-defects','Visual inspection',e.sections.defects,defectBody+(i.data.fields.defect_remarks?`<p class="muted record-note">${esc(i.data.fields.defect_remarks)}</p>`:''))}${recordDetailSection('record-tests','Performance tests',e.sections.tests,testBody)}${recordDetailSection('record-measurements','Measurements',e.sections.measurements,measurementBody)}${recordDetailSection('record-remarks','Inspection remarks',i.data.fields.remarks?'pass':'pending',`<p>${esc(i.data.fields.remarks||'No remarks recorded.')}</p>`)}</div></section>`;};
function recordMeasurementSampleBlockTable(i,title,metrics,start,count,totalSamples,singleReading){const end=Math.min(start+count,totalSamples);const rangeLabel=singleReading?'Reading':`Samples ${String(start+1).padStart(2,'0')}-${String(end).padStart(2,'0')}`;return `<div class="record-sample-block"><div class="record-sample-block-title">${esc(rangeLabel)}</div><div class="measurement-grid-wrap compact-measurement-wrap record-measurement-grid"><table class="measurement-grid compact-measurement-grid transposed-measurement-grid ${singleReading?'single-transposed-measurement-grid':''}" aria-label="${esc(title)} saved readings ${esc(rangeLabel)}"><thead><tr><th class="sticky-sample">Measurement</th>${Array.from({length:end-start},(_,n)=>`<th>${singleReading?'Reading':String(start+n+1).padStart(2,'0')}</th>`).join('')}<th class="disposition-col">Disposition</th></tr></thead><tbody>${metrics.map(m=>`<tr><th class="sticky-sample measurement-row-label"><span>${esc(recordMeasurementLabel(m))}</span><small>${esc(measurementLimitSummary(i,m))}</small></th>${Array.from({length:end-start},(_,n)=>recordMeasurementCell(i,m,start+n)).join('')}<td class="measurement-disposition-cell">${recordMeasurementDisposition(i,m)}</td></tr>`).join('')}</tbody></table></div></div>`;}
recordMeasurementGroupTable=function(i,title,metrics){if(!metrics.length)return'';const maxSamples=Math.max(...metrics.map(m=>m.samples));const singleReading=maxSamples===1;const blockSize=singleReading?1:6;const blocks=[];for(let start=0;start<maxSamples;start+=blockSize)blocks.push(recordMeasurementSampleBlockTable(i,title,metrics,start,blockSize,maxSamples,singleReading));return `<section class="measurement-group-panel record-measurement-panel"><div class="measurement-group-head"><h3>${esc(title)}</h3><span class="muted">${metrics.length} field${metrics.length===1?'':'s'}</span></div>${blocks.join('')}</section>`;};
function recordPrintMeasurementValue(i,m,n){const limit=i.spec?.limits?.[m.key]||{},values=i.data.measurements?.[m.key]||[];if(n>=m.samples||(limit.na&&i.data.section_flags?.[m.section]!=='pass'))return`<td class="muted-cell">--</td>`;const v=values[n],r=qrexEffectiveSectionResult(i,m.section,readingResult(v,limit));return `<td class="${r==='fail'?'failed':''}"><strong>${esc(v??'--')}</strong>${m.unit?` <small>${esc(m.unit)}</small>`:''}</td>`;}
function recordPrintMeasurementGroupTable(i,title,metrics){if(!metrics.length)return'';const maxSamples=Math.max(...metrics.map(m=>m.samples));return `<section class="record-pdf-measurement-panel"><div class="measurement-group-head"><h3>${esc(title)}</h3><span class="muted">${metrics.length} field${metrics.length===1?'':'s'}</span></div><table class="record-pdf-measurement-table" aria-label="${esc(title)} print readings by sample"><thead><tr><th>Sample</th>${metrics.map(m=>`<th><span>${esc(recordMeasurementLabel(m))}</span><small>${esc(measurementLimitSummary(i,m))}</small></th>`).join('')}</tr></thead><tbody>${Array.from({length:maxSamples},(_,n)=>`<tr><th>${String(n+1).padStart(2,'0')}</th>${metrics.map(m=>recordPrintMeasurementValue(i,m,n)).join('')}</tr>`).join('')}</tbody><tfoot><tr><th>Disposition</th>${metrics.map(m=>`<td>${recordMeasurementDisposition(i,m)}</td>`).join('')}</tr></tfoot></table></section>`;}
function recordPrintMeasurementsMatrix(i,metricKey=''){const metrics=S.meta.products[i.product].metrics.filter(m=>m.section==='measurements'&&(!metricKey||m.key===metricKey));if(!metrics.length)return'';if(metricKey)return recordPrintMeasurementGroupTable(i,recordMeasurementLabel(metrics[0]),metrics);const weightMetrics=metrics.filter(m=>m.key==='weight');const thicknessMetrics=metrics.filter(m=>m.key==='thickness');const dimensionMetrics=metrics.filter(m=>!['weight','thickness'].includes(m.key));return `<div class="record-measurement-print"><div class="measurement-top-grid">${recordPrintMeasurementGroupTable(i,'Weight',weightMetrics)}${recordPrintMeasurementGroupTable(i,'Thickness',thicknessMetrics)}</div>${recordPrintMeasurementGroupTable(i,'Dimensions',dimensionMetrics)}</div>`;}
recordMeasurementsMatrix=function(i,metricKey=''){const metrics=S.meta.products[i.product].metrics.filter(m=>m.section==='measurements'&&(!metricKey||m.key===metricKey));if(!metrics.length)return'<p class="muted">No measurement readings configured.</p>';if(metricKey)return `<div class="record-measurement-screen">${recordMeasurementGroupTable(i,recordMeasurementLabel(metrics[0]),metrics)}</div>${recordPrintMeasurementsMatrix(i,metricKey)}`;const weightMetrics=metrics.filter(m=>m.key==='weight');const thicknessMetrics=metrics.filter(m=>m.key==='thickness');const dimensionMetrics=metrics.filter(m=>!['weight','thickness'].includes(m.key));return `<div class="measurement-group-stack record-measurement-groups record-measurement-screen"><div class="measurement-top-grid">${recordMeasurementGroupTable(i,'Weight',weightMetrics)}${recordMeasurementGroupTable(i,'Thickness',thicknessMetrics)}</div>${recordMeasurementGroupTable(i,'Dimensions',dimensionMetrics)}</div>${recordPrintMeasurementsMatrix(i)}`;};
